using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capabilities to the research agent.
/// Uses a configurable search API (defaults to a simulated search for demo purposes).
/// Set the SEARCH_API_URL environment variable to use a real search endpoint.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<WebSearchTool> _logger;

    public WebSearchTool(HttpClient httpClient, ILogger<WebSearchTool> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    [Description("Searches the web for information on a given query. Returns a list of relevant results with titles, snippets, and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to find information about")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);
        _logger.LogInformation("Searching web for: {Query} (max {MaxResults} results)", query, maxResults);

        var searchApiUrl = Environment.GetEnvironmentVariable("SEARCH_API_URL");

        if (!string.IsNullOrEmpty(searchApiUrl))
        {
            return await SearchWithApiAsync(searchApiUrl, query, maxResults);
        }

        // Simulated search results for demonstration
        return GetSimulatedResults(query, maxResults);
    }

    private async Task<string> SearchWithApiAsync(string apiUrl, string query, int maxResults)
    {
        try
        {
            var requestUrl = $"{apiUrl}?q={Uri.EscapeDataString(query)}&count={maxResults}";
            var response = await _httpClient.GetAsync(requestUrl);
            response.EnsureSuccessStatusCode();
            var content = await response.Content.ReadAsStringAsync();
            return content;
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Search API call failed, falling back to simulated results");
            return GetSimulatedResults(query, maxResults);
        }
    }

    private static string GetSimulatedResults(string query, int maxResults)
    {
        var results = new List<object>
        {
            new { Title = $"Overview of {query}", Snippet = $"A comprehensive overview covering the key aspects of {query}, including history, current state, and future directions.", Url = $"https://example.com/overview-{Uri.EscapeDataString(query)}" },
            new { Title = $"Recent developments in {query}", Snippet = $"Latest research and breakthroughs related to {query} from 2025-2026, including new methodologies and findings.", Url = $"https://example.com/recent-{Uri.EscapeDataString(query)}" },
            new { Title = $"{query} - Technical deep dive", Snippet = $"An in-depth technical analysis of {query}, covering implementation details, challenges, and best practices.", Url = $"https://example.com/technical-{Uri.EscapeDataString(query)}" },
            new { Title = $"Impact and applications of {query}", Snippet = $"How {query} is being applied across industries, with case studies and measurable outcomes.", Url = $"https://example.com/applications-{Uri.EscapeDataString(query)}" },
            new { Title = $"Future outlook: {query}", Snippet = $"Expert predictions and trends for the future of {query}, including potential disruptions and opportunities.", Url = $"https://example.com/future-{Uri.EscapeDataString(query)}" },
        };

        var trimmed = results.Take(maxResults).ToList();
        return JsonSerializer.Serialize(trimmed, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using System.Text;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capabilities to the research agent.
/// The agent can save, list, and retrieve notes collected during research.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<ResearchNote> _notes = [];
    private readonly ILogger<NoteTakingTool> _logger;

    public NoteTakingTool(ILogger<NoteTakingTool> logger)
    {
        _logger = logger;
    }

    [Description("Saves a research note with a title, content, and optional source URL. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short title for the note")] string title,
        [Description("The content/body of the note")] string content,
        [Description("The source URL where this information was found (optional)")] string? sourceUrl = null)
    {
        var note = new ResearchNote
        {
            Id = _notes.Count + 1,
            Title = title,
            Content = content,
            SourceUrl = sourceUrl,
            CreatedAt = DateTimeOffset.UtcNow,
        };

        _notes.Add(note);
        _logger.LogInformation("Note saved: [{Id}] {Title}", note.Id, note.Title);
        return $"Note #{note.Id} saved: \"{title}\"";
    }

    [Description("Lists all saved research notes with their IDs and titles.")]
    public string ListNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"Research notes ({_notes.Count} total):");
        foreach (var note in _notes)
        {
            sb.AppendLine($"  [{note.Id}] {note.Title} (Source: {note.SourceUrl ?? "N/A"})");
        }

        return sb.ToString();
    }

    [Description("Retrieves the full content of a specific note by its ID.")]
    public string GetNote([Description("The ID of the note to retrieve")] int noteId)
    {
        var note = _notes.FirstOrDefault(n => n.Id == noteId);
        if (note is null)
        {
            return $"Note #{noteId} not found.";
        }

        return $"[{note.Id}] {note.Title}\nSource: {note.SourceUrl ?? "N/A"}\nCreated: {note.CreatedAt:u}\n\n{note.Content}";
    }

    [Description("Gets all saved notes formatted as a research summary.")]
    public string GetAllNotesForSummary()
    {
        if (_notes.Count == 0)
        {
            return "No research notes have been collected.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===\n");
        foreach (var note in _notes)
        {
            sb.AppendLine($"--- [{note.Id}] {note.Title} ---");
            if (note.SourceUrl is not null)
            {
                sb.AppendLine($"Source: {note.SourceUrl}");
            }

            sb.AppendLine(note.Content);
            sb.AppendLine();
        }

        return sb.ToString();
    }

    private sealed class ResearchNote
    {
        public int Id { get; init; }
        public required string Title { get; init; }
        public required string Content { get; init; }
        public string? SourceUrl { get; init; }
        public DateTimeOffset CreatedAt { get; init; }
    }
}

