using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

// Configure logging
builder.Logging.SetMinimumLevel(LogLevel.Information);
builder.Logging.AddSimpleConsole(options =>
{
    options.SingleLine = true;
    options.TimestampFormat = "HH:mm:ss ";
});

// Register HttpClient for web search
builder.Services.AddHttpClient<WebSearchTool>();

// Register tool instances as singletons (they hold state within a session)
builder.Services.AddSingleton<NoteTakingTool>();

// Register the IChatClient via MEAI abstraction
builder.Services.AddChatClient(chatClientBuilder =>
{
    var apiKey = builder.Configuration["AI:ApiKey"]
        ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
        ?? throw new InvalidOperationException(
            "OpenAI API key not configured. Set AI:ApiKey in appsettings.json, " +
            "user-secrets, or the OPENAI_API_KEY environment variable.");

    var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

    var openAiClient = new OpenAIClient(apiKey);
    chatClientBuilder.UseOpenAIChatClient(modelId, openAiClient);
});

var host = builder.Build();

// Resolve services
var chatClient = host.Services.GetRequiredService<IChatClient>();
var loggerFactory = host.Services.GetRequiredService<ILoggerFactory>();
var logger = loggerFactory.CreateLogger("ResearchAgent");
var noteTakingTool = host.Services.GetRequiredService<NoteTakingTool>();
var webSearchTool = host.Services.GetRequiredService<WebSearchTool>();

// Define the tools the agent can use
var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTakingTool.SaveNote),
    AIFunctionFactory.Create(noteTakingTool.ListNotes),
    AIFunctionFactory.Create(noteTakingTool.GetNote),
    AIFunctionFactory.Create(noteTakingTool.GetAllNotesForSummary),
};

// Create the research agent using Microsoft Agent Framework
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using multiple queries
        2. Taking detailed notes on key findings using the note-taking tool
        3. After gathering enough information, retrieving all notes and providing a comprehensive summary

        Research strategy:
        - Start with a broad search, then narrow down to specific aspects
        - Save notes for each important finding with clear titles
        - Include source URLs in your notes when available
        - Aim for 3-5 searches to cover the topic well
        - End by summarizing all collected notes into a cohesive research report
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes",
    tools: tools,
    loggerFactory: loggerFactory);

// Get the research topic
string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine() ?? "artificial intelligence trends in 2026";
}

logger.LogInformation("Starting research on: {Topic}", topic);
Console.WriteLine($"\n🔍 Researching: {topic}\n");

// Run the agent
